import{_ as a,o as t,c as i,ag as s}from"./chunks/framework.CbQjVMS6.js";const g=JSON.parse('{"title":"Why agents need a search engine, not an answer machine","description":"","frontmatter":{},"headers":[],"relativePath":"insights/agent-native-knowledge.md","filePath":"insights/agent-native-knowledge.md","lastUpdated":1794023466000}'),n={name:"insights/agent-native-knowledge.md"};function r(o,e,l,h,d,c){return t(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="why-agents-need-a-search-engine-not-an-answer-machine" tabindex="-1">Why agents need a search engine, not an answer machine <a class="header-anchor" href="#why-agents-need-a-search-engine-not-an-answer-machine" aria-label="Permalink to &quot;Why agents need a search engine, not an answer machine&quot;">​</a></h1><p><em>Published 6 November 2026 · 7 min read</em></p><p>When people add knowledge to an AI system, the first instinct is usually to build an answer machine. Upload the documents, ask a question, receive a paragraph. The appeal is obvious: the interaction feels finished. The problem is that it hides where the answer came from and collapses every possible question into a single response.</p><p>Agents work differently. A coding agent investigating a bug, a research agent comparing three approaches, or an operations agent checking a policy does not want one authoritative paragraph. It wants to issue several queries, follow references, read the relevant source in full and reach its own conclusion. That is much closer to how a person uses a search engine than how a person uses a chatbot.</p><h2 id="retrieval-is-a-loop-not-a-lookup" tabindex="-1">Retrieval is a loop, not a lookup <a class="header-anchor" href="#retrieval-is-a-loop-not-a-lookup" aria-label="Permalink to &quot;Retrieval is a loop, not a lookup&quot;">​</a></h2><p>A useful agent session looks like this:</p><ol><li>The agent forms a rough query from the task.</li><li>It receives a ranked list of candidate pages, each with a title and a short summary.</li><li>It reads one or two pages in full.</li><li>It discovers a term it did not know and searches again.</li><li>It follows links to related material.</li><li>It cites the pages it used and stops when the evidence is sufficient.</li></ol><p>Each step depends on the previous one. If the knowledge system only returns a generated answer, the agent cannot inspect the evidence, cannot notice that a claim is outdated, and cannot correct its own search direction. The loop collapses into a single opaque turn.</p><p>This is why PieKBS exposes <code>kb_search</code> and <code>kb_page</code> rather than an <code>ask</code> tool. Search returns pages; page returns the full document. The agent decides what to read and when to stop. The system&#39;s job is to make sure the right pages are findable and readable.</p><h2 id="the-unit-of-retrieval-matters" tabindex="-1">The unit of retrieval matters <a class="header-anchor" href="#the-unit-of-retrieval-matters" aria-label="Permalink to &quot;The unit of retrieval matters&quot;">​</a></h2><p>Most retrieval-augmented generation systems split documents into fixed-size chunks. Chunking is a compromise: small chunks improve matching but lose context, large chunks preserve context but dilute relevance. A chunk-based system also makes it hard to answer questions that require reading a whole procedure, because the answer is spread across several fragments.</p><p>A structured wiki makes a different trade. Each page has a topic, a stable identity and a set of source links. Pages are written to be read in full. Search operates on pages, not arbitrary windows. That gives the agent a clean unit of evidence: &quot;this page, from these sources, updated on this date.&quot;</p><p>The trade-off is authoring effort. Someone or something must distill source material into pages. PieKBS automates the first pass with a distillation pipeline, but it keeps the output in Markdown so a human can review, correct and version it. The knowledge base is a maintained artifact, not a one-time index.</p><h2 id="search-quality-beats-vector-similarity-alone" tabindex="-1">Search quality beats vector similarity alone <a class="header-anchor" href="#search-quality-beats-vector-similarity-alone" aria-label="Permalink to &quot;Search quality beats vector similarity alone&quot;">​</a></h2><p>Vector search is good at finding passages that are semantically close to a query. It is less good at exact identifiers, product codes, error messages and rare terms, where lexical matching is often decisive. It also struggles to explain why a result ranked where it did.</p><p>A practical knowledge system usually benefits from hybrid retrieval:</p><ul><li><strong>Lexical search</strong> (BM25 over SQLite FTS5 or PostgreSQL full-text search) for exact terms, names and codes.</li><li><strong>Structural signals</strong> such as page type, recency, inbound links and source count.</li><li><strong>Optional embeddings</strong> for paraphrase matching, fused with lexical results rather than replacing them.</li></ul><p>PieKBS starts with lexical search and structure because it is fast, local and explainable. Embeddings can be added, but they are not a prerequisite for a useful knowledge base. This ordering matters: if the underlying pages are poorly organised, better similarity search will only retrieve poor pages more confidently.</p><h2 id="auditability-is-a-feature" tabindex="-1">Auditability is a feature <a class="header-anchor" href="#auditability-is-a-feature" aria-label="Permalink to &quot;Auditability is a feature&quot;">​</a></h2><p>A generated answer is hard to audit. A Markdown page is easy. You can open it, read it, compare two revisions with <code>git diff</code>, run a link checker, and see which sources it cites. When an agent cites that page, a human can follow the same path.</p><p>This is not nostalgia for plain text. It is an operational requirement. Knowledge that cannot be reviewed will drift. A page that contradicts another page can be found and fixed. A stale claim can be updated in one place. A missing source can be flagged. None of that is possible when knowledge exists only as an opaque embedding.</p><h2 id="what-this-means-in-practice" tabindex="-1">What this means in practice <a class="header-anchor" href="#what-this-means-in-practice" aria-label="Permalink to &quot;What this means in practice&quot;">​</a></h2><p>If you are building a knowledge layer for agents, start with these questions:</p><ul><li><strong>What is the unit of knowledge?</strong> Prefer a stable, readable page over an arbitrary chunk.</li><li><strong>Can the agent read the whole thing?</strong> Search results should lead to full documents, not fragments.</li><li><strong>Can a human review a change?</strong> Keep the knowledge layer in a diffable format.</li><li><strong>Does search handle exact terms?</strong> Include lexical retrieval, not only embeddings.</li><li><strong>Are sources visible?</strong> Every synthesized page should link back to its evidence.</li><li><strong>Can the agent stop?</strong> Provide enough structure for the agent to judge when the evidence is sufficient.</li></ul><p>An answer machine optimises for the first question a user asks. A search engine optimises for the second, third and fourth questions that follow. Agents ask all of them.</p><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://pieteams.github.io/piekbs/getting-started/what-is-piekbs" target="_blank" rel="noreferrer">What is PieKBS</a> — the design and structure of the knowledge base</li><li><a href="/insights/rag-vs-llm-wiki">RAG vs. LLM wiki</a> — how the two approaches compare</li><li><a href="https://pieteams.github.io/piekbs/guide/how-agents-use" target="_blank" rel="noreferrer">How agents use PieKBS</a> — the retrieval loop in detail</li></ul>',27)])])}const p=a(n,[["render",r]]);export{g as __pageData,p as default};
